const crypto = require('crypto');

function uuidv5(name, namespaceHex) {
  const namespaceBytes = Buffer.from(namespaceHex.replace(/-/g, ''), 'hex');
  const nameBytes = Buffer.from(name, 'utf8');
  const hash = crypto.createHash('sha1').update(Buffer.concat([namespaceBytes, nameBytes])).digest();
  const bytes = Buffer.from(hash.subarray(0, 16));
  bytes[6] = (bytes[6] & 0x0f) | 0x50; // version 5
  bytes[8] = (bytes[8] & 0x3f) | 0x80; // variant RFC4122
  const hex = bytes.toString('hex');
  return `${hex.substring(0,8)}-${hex.substring(8,12)}-${hex.substring(12,16)}-${hex.substring(16,20)}-${hex.substring(20)}`;
}

// Namespace fijo y arbitrario, propio de Baby's World, para no chocar con otros usos de UUIDv5.
const NAMESPACE = '2b3c1a10-babe-5c00-8f00-babysworldns0';
// crypto.createHash necesita un namespace valido en hex de 16 bytes; se deriva uno estable a partir del texto anterior.
const NAMESPACE_HEX = crypto.createHash('md5').update(NAMESPACE).digest('hex');

const input = $input.first().json ?? {};
const variantId = input.payload?.variant_id ?? null;

// Cambio de diseno (2026-08-13): el id deterministico SIEMPRE se calcula a partir de
// variant_id, nunca del SKU. variant_id lo asigna Shopify una sola vez por variante y
// no cambia en toda su vida, aunque despues le agreguen o editen el SKU -- asi el id de
// Qdrant queda estable desde el primer evento. Si se usara el SKU cuando existe y
// variant_id solo como fallback, el id cambiaria el dia que a una variante sin SKU se le
// agrega uno, dejando un punto viejo huerfano y duplicado en Qdrant (el flujo de upsert
// no sabe que antes esa variante vivia en otro id). El SKU se sigue guardando como dato
// dentro del payload, pero ya no participa del calculo del id.
const key = (variantId !== null && variantId !== undefined && String(variantId).trim() !== '') ? `variant-${variantId}` : '';

if (!key) {
  return [{ json: { ...input, qdrant_point_id: null, id_error: 'missing_variant_id' } }];
}

const qdrantPointId = uuidv5(`babysworld-product-${key}`, NAMESPACE_HEX);

return [{ json: { ...input, qdrant_point_id: qdrantPointId } }];

// Rama de error de 'Qdrant_Upsert_Point'. El shape exacto del item de error puede
// variar segun la version de n8n, asi que se revisa el JSON completo como texto en
// vez de asumir una key especifica.
const err = $input.first().json;
const text = JSON.stringify(err ?? {}).toLowerCase();
const missing = text.includes("doesn't exist") || text.includes('does not exist');

return [{ json: { collection_missing: missing, error_raw: err } }];

// La coleccion SI existe -- el error de 'Qdrant_Upsert_Point' es otra cosa (credenciales,
// payload invalido, etc.). No se autoprovisiona nada: se relanza el error original tal
// cual, para que la ejecucion quede en estado de error como antes de este fix.
const err = $json.error_raw;
throw new Error(typeof err === 'string' ? err : JSON.stringify(err));

